%%================================
enc_MessageFeed(Val) ->
    enc_MessageFeed(Val, []).

enc_MessageFeed(Val, TagIn) ->
   {EncBytes,EncLen} = case element(1,Val) of
      p2p ->
         'enc_P2P'(element(2,Val), [<<48>>,<<160>>]);
      muc ->
         'enc_MUC'(element(2,Val), [<<48>>,<<161>>]);
      chan ->
         'enc_Channel'(element(2,Val), [<<48>>,<<162>>]);
      Else -> 
         exit({error,{asn1,{invalid_choice_type,Else}}})
   end,

encode_tags(TagIn, EncBytes, EncLen).




dec_MessageFeed(Tlv) ->
   dec_MessageFeed(Tlv, []).

dec_MessageFeed(Tlv, TagIn) ->
Tlv1 = match_tags(Tlv, TagIn),
case (case Tlv1 of [CtempTlv1] -> CtempTlv1; _ -> Tlv1 end) of

%% 'p2p'
    {131072, V1} -> 
        {p2p, 'dec_P2P'(V1, [16])};


%% 'muc'
    {131073, V1} -> 
        {muc, 'dec_MUC'(V1, [16])};


%% 'chan'
    {131074, V1} -> 
        {chan, 'dec_Channel'(V1, [16])};

      Else -> 
         exit({error,{asn1,{invalid_choice_tag,Else}}})
   end
.


